import React, { useEffect, useState } from 'react';
import { FaPlane } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';

const DecorativePlanes = () => {
  const { theme } = useTheme();
  const [planes, setPlanes] = useState([]);

  useEffect(() => {
    // Create initial planes
    const initialPlanes = Array.from({ length: 5 }, (_, index) => ({
      id: index,
      startX: Math.random() * 100,
      startY: Math.random() * 100,
      endX: Math.random() * 100,
      endY: Math.random() * 100,
      duration: 15 + Math.random() * 20, // Random duration between 15-35s
      delay: Math.random() * 10, // Random delay between 0-10s
      size: 12 + Math.random() * 8, // Random size between 12-20px
      rotation: Math.random() * 360 // Random initial rotation
    }));
    setPlanes(initialPlanes);

    // Update plane positions periodically
    const interval = setInterval(() => {
      setPlanes(currentPlanes => 
        currentPlanes.map(plane => ({
          ...plane,
          startX: plane.endX,
          startY: plane.endY,
          endX: Math.random() * 100,
          endY: Math.random() * 100,
          duration: 15 + Math.random() * 20,
          delay: 0,
          rotation: Math.random() * 360
        }))
      );
    }, 35000); // Update every 35 seconds

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none overflow-hidden" style={{ zIndex: 0 }}>
      {planes.map(plane => (
        <div
          key={plane.id}
          className="absolute"
          style={{
            left: `${plane.startX}%`,
            top: `${plane.startY}%`,
            transform: `rotate(${plane.rotation}deg)`,
            animation: `fly ${plane.duration}s linear ${plane.delay}s infinite`,
            opacity: 0.3,
            color: theme.primary
          }}
        >
          <FaPlane size={plane.size} />
        </div>
      ))}

      <style jsx>{`
        @keyframes fly {
          0% {
            transform: translate(0, 0) rotate(${planes[0]?.rotation}deg);
            opacity: 0;
          }
          10% {
            opacity: 0.3;
          }
          90% {
            opacity: 0.3;
          }
          100% {
            transform: translate(
              calc(${planes[0]?.endX}vw - ${planes[0]?.startX}vw),
              calc(${planes[0]?.endY}vh - ${planes[0]?.startY}vh)
            ) rotate(${planes[0]?.rotation}deg);
            opacity: 0;
          }
        }
      `}</style>
    </div>
  );
};

export default DecorativePlanes;
